sales-bento:
const centers = [...new Map(salesRecords.map(record => [record.centerId, { id: record.centerId, name: record.centerName }])).values()]
const periods = [...new Set(salesRecords.map(record => record.period))].sort().reverse()
const query = (value: unknown) => typeof value === 'string' ? value : ''
const center = computed({
  get: () => centers.some(item => item.id === query(route.query.center)) ? query(route.query.center) : 'novo-peredelkino',
  set: value => { void router.replace({ query: { ...route.query, center: value, period: period.value } }) },
})
const period = computed({
  get: () => periods.includes(query(route.query.period)) ? query(route.query.period) : periods[0],
  set: value => { void router.replace({ query: { ...route.query, center: center.value, period: value } }) },
})

